import json
from decimal import Decimal
from urllib.parse import urlencode

import pytest
from django.core.management import CommandError, call_command
from django.test import Client

from parameters.catalog import CatalogError
from parameters.services import REVISION, load_rules
from simulation import services


URL = "/simples/servicos/"
# Independent calendar and payroll fixture, not generated by the simulator.
MONTHS = tuple(f"2026-{month:02}" for month in range(2, 13)) + ("2027-01",)


@pytest.fixture
def inputs():
    data = dict(edition=REVISION, period="2027-03", opening="2026-02", regime="traditional",
                activity="software", limits="within", treatment="ordinary", origin="synthetic", revenue="100000")
    for month in MONTHS:
        for key, value in dict(turnover="100000", wages="20000", pro_labore="5000", cpp="2000", fgts="1000").items():
            data[f"{key}_{month}"] = value
    return data


def post(client, data):
    return client.post(URL, urlencode(data, doseq=True), content_type="application/x-www-form-urlencoded")


@pytest.mark.parametrize("last_pay,annex,rate,das,allocation,residue", [
    ("19999,99", "V", "19.075", "19075", ["4005.75","2861.25","3612.81","4549.39","4005.75","40.06"], "0.01"),
    ("20000", "III", "13.03", "13030", ["521.20","456.05","2138.22","5655.02","4234.75","24.76"], "0"),
    ("20000,01", "III", "13.03", "13030", ["521.20","456.05","2138.22","5655.02","4234.75","24.76"], "0"),
])
def test_c08_one_cent(client, inputs, last_pay, annex, rate, das, allocation, residue):
    inputs["wages_2027-01"] = last_pay
    response = post(client, inputs)
    assert response.status_code == 200
    m = response.context["memory"]
    assert m["history"]["months"] == MONTHS
    assert m["history"]["fs12"] == Decimal("316000") + Decimal(last_pay.replace(",", "."))
    assert m["history"]["rbt12r"] == 1200000
    assert m["factor"]["annex"] == annex and m["band"]["number"] == 4
    a = m["amounts"]
    assert a["effective_percent"] == Decimal(rate) and a["monthly"] == Decimal(das)
    assert {r["tax"]: r["displayed"] for r in a["rows"]} == dict(zip(
        ["IRPJ", "CSLL", "CBS", "CPP", "ISS", "IBS"], map(Decimal, allocation)))
    assert a["residue"] == Decimal(residue)
    assert m["engines"] == [] and not a["iss_capped"]
    if annex == "V":
        assert b"27,999999167%" in response.content


@pytest.mark.parametrize("key,known", [("turnover_2027-01", "fs12"), ("fgts_2026-02", "rbt12r"),
                                        ("cpp_2026-05", "rbt12r"), ("wages_2026-03", "rbt12r")])
def test_incomplete_month(client, inputs, key, known):
    del inputs[key]
    m = post(client, inputs).context["memory"]
    assert m["state"] == "Parcial" and m["history"][known] is not None
    assert "amounts" not in m and "factor" not in m
    component, month = key.split("_", 1)
    assert m["history"]["missing"][component] == [month]


@pytest.mark.parametrize("pay,turnover,factor,annex,monthly", [
    ("0", "0", "0.01", "V", "15500"), ("1", "0", "0.28", "III", "6000"),
    ("0", "1000", "0.01", "V", "15500"),
])
def test_zero_rules_and_rate_basis(client, inputs, pay, turnover, factor, annex, monthly):
    for month in MONTHS:
        for key in ("wages", "pro_labore", "cpp", "fgts"):
            inputs[f"{key}_{month}"] = pay if key == "wages" else "0"
        inputs["turnover_" + month] = turnover
    m = post(client, inputs).context["memory"]
    assert m["factor"]["ratio"] == Decimal(factor) and m["factor"]["annex"] == annex
    assert m["rate_basis"] == (Decimal(turnover) * 12 or 1)
    assert m["amounts"]["monthly"] == Decimal(monthly)


@pytest.mark.parametrize("total,band", [
    ("180000", 1), ("180000.01", 2), ("360000", 2), ("360000.01", 3),
    ("720000", 3), ("720000.01", 4), ("1800000", 4), ("1800000.01", 5),
    ("3600000", 5), ("3600000.01", 6), ("4800000", 6), ("4800000.01", None),
])
def test_bands(client, inputs, total, band):
    for month in MONTHS:
        inputs["turnover_" + month] = total if month == MONTHS[0] else "0"
    m = post(client, inputs).context["memory"]
    assert (m["band"]["number"] if m["band"] else None) == band
    if band in (6, None):
        assert "amounts" not in m


def test_iss_cap(client, inputs):
    # RBT12 3M; (630000 - 125640) / 3M = 16.812%. ISS capped at 5% of March.
    for month in MONTHS:
        inputs["turnover_" + month] = "250000"
        inputs["wages_" + month] = "75000"
    a = post(client, inputs).context["memory"]["amounts"]
    assert a["iss_capped"] and a["monthly"] == 16812
    parts = {r["tax"]: r["displayed"] for r in a["rows"]}
    assert parts["ISS"] == 5000 and parts["IBS"] == Decimal("30.71")
    assert parts["CPP"] == Decimal("7708.51")
    assert sum(r["exact"] for r in a["rows"]) == 16812


@pytest.mark.parametrize("revenue,monthly", [("0","0"), ("0.01","0.01"), ("50","6.52")])
def test_rounding(client, inputs, revenue, monthly):
    m = post(client, dict(inputs, revenue=revenue)).context["memory"]
    assert m["amounts"]["monthly"] == Decimal(monthly)
    if revenue == "0.01":
        assert m["amounts"]["sum_displayed"] == Decimal("0.06")


@pytest.mark.parametrize("key,value", [("period","2027-02"), ("activity","other"), ("regime","other"),
                                        ("opening","2026-03"), ("activity","unknown")])
def test_out_of_scope(client, inputs, key, value):
    m = post(client, dict(inputs, **{key:value})).context["memory"]
    assert m["reasons"] and "factor" not in m and "amounts" not in m


@pytest.mark.parametrize("key,value", [("treatment","unknown"), ("limits","excess"), ("revenue",""),
                                        ("turnover_2026-02","3200000"), ("revenue","3500000.01")])
def test_partial_preserves_factor(client, inputs, key, value):
    m = post(client, dict(inputs, **{key:value})).context["memory"]
    assert m["reasons"] and "factor" in m and "amounts" not in m


@pytest.mark.parametrize("changes", [
    {"revenue":["100","200"]}, {"cpf":"123"}, {"fgts_2027-02":"0"}, {"opening":"2027-04"},
    {"revenue":"-0.01"}, {"revenue":"1,234"}, {"turnover_2027-01":"NaN"},
    {"edition":"old"}, {"csrfmiddlewaretoken":["a","b"]}, {"example":["boundary","boundary"]},
])
def test_invalid_posts(client, inputs, changes):
    response = post(client, dict(inputs, **changes))
    assert response.status_code == 400 and response.context["memory"] is None


def test_start_and_refine(client, inputs):
    assert URL in client.get("/").content.decode()
    assert "no-store" in client.get(URL)["Cache-Control"]
    assert client.get(URL+"?revenue=10").status_code == 400
    assert post(Client(enforce_csrf_checks=True), inputs).status_code == 403
    response = post(client, {"example":"boundary"})
    assert response.context["form"]["wages_2027-01"].value() == "20000"
    assert response.context["memory"] is None
    response = post(client, dict(inputs, revenue=""))
    assert response.context["form"]["fgts_2026-02"].value() == "1000"
    assert response.context["memory"]["state"] == "Parcial"
    assert post(client, inputs).context["memory"]["amounts"]["monthly"] == 13030


def test_revision_unavailable(client, inputs, monkeypatch):
    def unavailable():
        raise CatalogError("Revisão indisponível.")
    monkeypatch.setattr(services, "load_rules", unavailable)
    response = post(client, inputs)
    assert response.status_code == 503 and "amounts" not in response.context["memory"]


def test_replay(client, inputs, tmp_path):
    file = tmp_path / "memory.json"
    record = post(client, inputs).context["replay"]
    file.write_text(record, encoding="utf-8")
    call_command("replay_services", file)
    modified = json.loads(record)
    modified["inputs"]["history"][MONTHS[0]]["wages"] = "0"
    file.write_text(json.dumps(modified), encoding="utf-8")
    with pytest.raises(CommandError, match="divergiu"):
        call_command("replay_services", file)


def test_catalog_invariants():
    rules = load_rules()
    assert sum(map(Decimal, rules["capped_remainder_percent"].values())) == 100
    for bands in rules["annexes"].values():
        previous = "0"
        for band in bands:
            assert band["above"] == previous
            previous = band["through"]
            if band["number"] < 6:
                assert sum(map(Decimal, band["shares"].values())) == 100
